# cellular automaton step (Game of Life)
g={(1,0),(1,1),(1,2)}
def step(g):
    ns={}
    for (x,y) in g:
        for dx in(-1,0,1):
            for dy in(-1,0,1):
                if dx or dy: ns[(x+dx,y+dy)]=ns.get((x+dx,y+dy),0)+1
    return {(x,y) for (x,y),n in ns.items() if n==3 or (n==2 and (x,y) in g)}
